package com.bananalab.lite;
import android.content.*;import android.database.*;import android.database.sqlite.*;import java.util.*;
/** Android FTS4 index; full documents never enter a CursorWindow. */
final class NotebookSQLite extends SQLiteOpenHelper implements NotebookDisk.Index{
 NotebookSQLite(Context c){this(c,"banana-knowledge-v2.db");}
 NotebookSQLite(Context c,String name){super(c,name,null,1);setWriteAheadLoggingEnabled(true);}
 public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE meta(k TEXT PRIMARY KEY,v TEXT NOT NULL)");db.execSQL("CREATE TABLE docs(id TEXT PRIMARY KEY,title TEXT,source TEXT,origin TEXT,saved INTEGER,bytes INTEGER,chars INTEGER,file TEXT,sha TEXT,truncated INTEGER)");db.execSQL("CREATE TABLE chunks(cid INTEGER PRIMARY KEY,docid TEXT NOT NULL,ord INTEGER NOT NULL,body TEXT NOT NULL,hint INTEGER NOT NULL)");db.execSQL("CREATE INDEX chunks_doc ON chunks(docid,ord)");db.execSQL("CREATE INDEX chunks_hint ON chunks(hint,cid)");db.execSQL("CREATE VIRTUAL TABLE lex USING fts4(tokens)");}
 public void onUpgrade(SQLiteDatabase db,int old,int version){throw new IllegalStateException("Migración de índice desconocida; conservé sus archivos");}
 SQLiteDatabase db(){return getWritableDatabase();}public void begin(){db().beginTransaction();}public void end(boolean commit){if(!db().inTransaction())return;if(commit)db().setTransactionSuccessful();db().endTransaction();}
 public String meta(String key){try(Cursor c=db().rawQuery("SELECT v FROM meta WHERE k=?",new String[]{key})){return c.moveToFirst()?c.getString(0):"";}}
 public void meta(String key,String value){ContentValues v=new ContentValues();v.put("k",key);v.put("v",value);if(db().insertWithOnConflict("meta",null,v,SQLiteDatabase.CONFLICT_REPLACE)<0)throw new SQLiteException("No pude guardar el estado del índice");}
 NotebookDisk.Doc read(Cursor c){NotebookDisk.Doc d=new NotebookDisk.Doc();d.id=c.getString(0);d.title=c.getString(1);d.source=c.getString(2);d.origin=c.getString(3);d.saved=c.getLong(4);d.bytes=c.getLong(5);d.chars=c.getInt(6);d.file=c.getString(7);d.sha=c.getString(8);d.truncated=c.getInt(9)!=0;return d;}
 static final String COLS="id,title,source,origin,saved,bytes,chars,file,sha,truncated";
 public List<NotebookDisk.Doc> list(int limit){List<NotebookDisk.Doc> rows=new ArrayList<>();try(Cursor c=db().rawQuery("SELECT "+COLS+" FROM docs ORDER BY saved DESC,id LIMIT "+Math.min(NotebookDisk.MAX_DOCUMENTS,limit),null)){while(c.moveToNext())rows.add(read(c));}return rows;}
 public NotebookDisk.Doc get(String id){try(Cursor c=db().rawQuery("SELECT "+COLS+" FROM docs WHERE id=?",new String[]{id})){return c.moveToFirst()?read(c):null;}}
 long number(String sql){try(Cursor c=db().rawQuery(sql,null)){return c.moveToFirst()?c.getLong(0):0;}}public long bytes(){return number("SELECT COALESCE(SUM(bytes),0) FROM docs");}public int count(){return (int)number("SELECT COUNT(*) FROM docs");}public long chunks(){return number("SELECT COUNT(*) FROM chunks");}
 public void remove(String id){db().execSQL("DELETE FROM lex WHERE docid IN (SELECT cid FROM chunks WHERE docid=?)",new Object[]{id});db().delete("chunks","docid=?",new String[]{id});db().delete("docs","id=?",new String[]{id});}
 public void doc(NotebookDisk.Doc d){ContentValues v=new ContentValues();v.put("id",d.id);v.put("title",d.title);v.put("source",d.source);v.put("origin",d.origin);v.put("saved",d.saved);v.put("bytes",d.bytes);v.put("chars",d.chars);v.put("file",d.file);v.put("sha",d.sha);v.put("truncated",d.truncated?1:0);db().insertOrThrow("docs",null,v);}
 public void chunk(String id,int ord,String text,String tokens,boolean hint){ContentValues v=new ContentValues();v.put("docid",id);v.put("ord",ord);v.put("body",text);v.put("hint",hint?1:0);long cid=db().insertOrThrow("chunks",null,v);db().execSQL("INSERT INTO lex(docid,tokens) VALUES(?,?)",new Object[]{cid,tokens});}
 String match(Set<String> terms,String op){StringBuilder s=new StringBuilder();int n=0;for(String t:terms)if(t.matches("[a-z0-9]+")){if(n++>0)s.append(op);s.append('"').append(t).append('"');if(n>=16)break;}return s.toString();}
 List<String> matchingDocs(String match){List<String> ids=new ArrayList<>();try(Cursor c=db().rawQuery("SELECT DISTINCT c.docid FROM lex JOIN chunks c ON c.cid=lex.docid JOIN docs d ON d.id=c.docid WHERE lex MATCH ? ORDER BY CASE WHEN d.origin='user' AND d.title='Corrección del usuario' THEN 0 ELSE 1 END,d.saved DESC LIMIT 12",new String[]{match})){while(c.moveToNext())ids.add(c.getString(0));}return ids;}
 List<Integer> matchingOrdinals(String id,String match){List<Integer> ord=new ArrayList<>();try(Cursor c=db().rawQuery("SELECT c.ord FROM lex JOIN chunks c ON c.cid=lex.docid WHERE lex MATCH ? AND c.docid=? ORDER BY c.ord LIMIT 8",new String[]{match,id})){while(c.moveToNext())ord.add(c.getInt(0));}return ord;}
 String window(String id,int ordinal){StringBuilder s=new StringBuilder();try(Cursor c=db().rawQuery("SELECT body FROM chunks WHERE docid=? AND ord BETWEEN ? AND ? ORDER BY ord",new String[]{id,Integer.toString(Math.max(0,ordinal-1)),Integer.toString(ordinal+1)})){while(c.moveToNext())s.append(c.getString(0)).append(' ');}return s.toString();}
 public List<NotebookDisk.Hit> search(Set<String> terms,int limit){List<NotebookDisk.Hit> hits=new ArrayList<>();String all=match(terms," AND "),any=match(terms," OR ");if(all.isEmpty())return hits;LinkedHashSet<String> ids=new LinkedHashSet<>(matchingDocs(all));if(ids.size()<12)ids.addAll(matchingDocs(any));int docs=0;for(String id:ids){if(docs++>=12)break;NotebookDisk.Doc d=get(id);List<Integer> ord=matchingOrdinals(id,all);if(ord.isEmpty())ord=matchingOrdinals(id,any);int last=-3;for(int n:ord){if(n-last<=1)continue;hits.add(new NotebookDisk.Hit(d,window(id,n)));last=n;if(hits.size()>=Math.min(96,limit))return hits;}}return hits;}
 public List<NotebookDisk.Hit> sample(int limit){List<NotebookDisk.Hit> out=new ArrayList<>();try(Cursor c=db().rawQuery("SELECT docid,body FROM chunks WHERE hint=1 ORDER BY cid DESC LIMIT "+Math.min(64,limit),null)){while(c.moveToNext())out.add(new NotebookDisk.Hit(get(c.getString(0)),c.getString(1)));}return out;}
 public List<NotebookDisk.Hit> slice(String id,int ordinal,int limit){List<NotebookDisk.Hit> out=new ArrayList<>();NotebookDisk.Doc d=get(id);if(d==null)return out;try(Cursor c=db().rawQuery("SELECT ord,body FROM chunks WHERE docid=? AND ord>=? ORDER BY ord LIMIT "+Math.min(8,limit),new String[]{id,Integer.toString(ordinal)})){while(c.moveToNext())out.add(new NotebookDisk.Hit(d,c.getString(1),c.getInt(0)));}return out;}
 public List<NotebookDisk.Hit> first(String id,int limit){List<NotebookDisk.Hit> out=new ArrayList<>();NotebookDisk.Doc d=get(id);if(d==null)return out;try(Cursor c=db().rawQuery("SELECT body FROM chunks WHERE docid=? ORDER BY ord LIMIT "+Math.min(8,limit),new String[]{id})){while(c.moveToNext())out.add(new NotebookDisk.Hit(d,c.getString(0)));}return out;}
 public void clear(){db().execSQL("DELETE FROM lex");db().delete("chunks",null,null);db().delete("docs",null,null);}
}
